package vn.vinhkhang.warehouse;
import java.math.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;
final class Costing {
 static BigDecimal n(Object v){return RevenueReports.number(v);}
 static BigDecimal cost(Map<String,Object> m,String key){Object v=m.get(key);if(v==null||v.toString().isBlank())return null;try{BigDecimal d=new BigDecimal(v.toString());if(d.signum()<0||d.scale()>6||d.precision()>18)throw new Exception();return d;}catch(Exception e){throw new Api.Problem(400,"Giá vốn không hợp lệ");}}
 static BigDecimal sourceCost(JdbcTemplate db,long part,Long document,Long production){var rows=db.queryForList("SELECT SUM(quantity) quantity,SUM(CASE WHEN unit_cost IS NULL THEN quantity ELSE 0 END) unknown_quantity,SUM(quantity*unit_cost) amount FROM stock_movements WHERE part_id=? AND "+(document!=null?"document_id=?":"production_id=?"),part,document!=null?document:production);var r=rows.getFirst();if(n(r.get("QUANTITY")).signum()==0||n(r.get("UNKNOWN_QUANTITY")).signum()!=0)return null;return n(r.get("AMOUNT")).divide(n(r.get("QUANTITY")),6,RoundingMode.HALF_UP);}
 static void move(Api core,JdbcTemplate db,long part,BigDecimal quantity,Long document,Long production,BigDecimal explicit,boolean hasExplicit){
  db.update("INSERT INTO stock_balances(part_id,location_id,quantity) SELECT ?,1,0 WHERE NOT EXISTS(SELECT 1 FROM stock_balances WHERE part_id=? AND location_id=1)",part,part);
  var balance=db.queryForList("SELECT quantity,average_unit_cost FROM stock_balances WHERE part_id=? AND location_id=1 FOR UPDATE",part).getFirst();BigDecimal before=n(balance.get("QUANTITY")),after=before.add(quantity),average=(BigDecimal)balance.get("AVERAGE_UNIT_COST");if(after.signum()<0)throw new Api.Problem(409,"Không đủ tồn kho: "+db.queryForObject("SELECT name FROM parts WHERE id=?",String.class,part)+" (cần "+quantity.abs()+", còn "+before+")");
  BigDecimal movementCost=explicit;if(!hasExplicit){if(quantity.signum()<0)movementCost=average;else if(document!=null){var doc=db.queryForList("SELECT code,type FROM stock_documents WHERE id=?",document).getFirst();if(doc.get("CODE").toString().startsWith("DC-"))movementCost=null;else if(doc.get("TYPE").equals("IN")){var ls=db.queryForList("SELECT unit_cost FROM stock_document_lines WHERE document_id=? AND part_id=?",document,part);movementCost=ls.isEmpty()?null:(BigDecimal)ls.getFirst().get("UNIT_COST");}else movementCost=sourceCost(db,part,document,null);}else movementCost=sourceCost(db,part,null,production);}
  BigDecimal next=average;if(after.signum()==0)next=null;else if(quantity.signum()>0||hasExplicit){next=before.signum()==0?movementCost:average==null||movementCost==null?null:before.multiply(average).add(quantity.multiply(movementCost)).divide(after,6,RoundingMode.HALF_UP);}
  db.update("UPDATE stock_balances SET quantity=?,average_unit_cost=? WHERE part_id=? AND location_id=1",after,next,part);db.update("INSERT INTO stock_movements(part_id,location_id,quantity,document_id,production_id,unit_cost) VALUES(?,1,?,?,?,?)",part,quantity,document,production,movementCost);
 }
 static void productionCost(JdbcTemplate db,long order){var rows=db.queryForList("SELECT id FROM vehicles WHERE order_id=? ORDER BY id",order);var costs=db.queryForList("SELECT SUM(-quantity*unit_cost) amount,SUM(CASE WHEN unit_cost IS NULL THEN quantity ELSE 0 END) unknown_quantity FROM stock_movements WHERE production_id=?",order).getFirst();if(rows.isEmpty()||n(costs.get("UNKNOWN_QUANTITY")).signum()!=0)return;BigDecimal total=n(costs.get("AMOUNT")).setScale(2,RoundingMode.HALF_UP),each=total.divide(BigDecimal.valueOf(rows.size()),2,RoundingMode.DOWN);for(int i=0;i<rows.size();i++)db.update("UPDATE vehicles SET purchase_unit_cost=? WHERE id=?",i==rows.size()-1?total.subtract(each.multiply(BigDecimal.valueOf(rows.size()-1))):each,rows.get(i).get("ID"));}
}
